Test that the {{agentName}} agent loads correctly.

Create {{agentTestDir}}/{{agentName}}.test.ts with:

```typescript
import { test, expect } from "bun:test"
import { Agent } from "../../src/agent/agent"
import { Config } from "../../src/config/config"
import { Instance } from "../../src/project/instance"
import { tmpdir } from "../util/tmpdir"
import path from "path"

test("{{agentName}} agent loads from .opencode/agent/", async () => {
  await using tmp = await tmpdir({
    init: async (dir) => {
      // Copy the agent file
      const agentContent = await Bun.file(".opencode/agent/{{agentName}}.md").text()
      await Bun.write(
        path.join(dir, ".opencode/agent/{{agentName}}.md"),
        agentContent
      )
    },
  })

  await Instance.provide({
    directory: tmp.path,
    fn: async () => {
      const agent = await Agent.get("{{agentName}}")

      expect(agent).toBeDefined()
      expect(agent.name).toBe("{{agentName}}")
      expect(agent.description).toBeTruthy()
      expect(agent.mode).toMatch(/subagent|primary|all/)
      expect(agent.builtIn).toBe(false)
      expect(agent.permission).toBeDefined()
      expect(agent.tools).toBeDefined()
    },
  })
})

test("{{agentName}} agent has valid tool configuration", async () => {
  await using tmp = await tmpdir({
    init: async (dir) => {
      const agentContent = await Bun.file(".opencode/agent/{{agentName}}.md").text()
      await Bun.write(
        path.join(dir, ".opencode/agent/{{agentName}}.md"),
        agentContent
      )
    },
  })

  await Instance.provide({
    directory: tmp.path,
    fn: async () => {
      const agent = await Agent.get("{{agentName}}")

      // Tools should be an object with boolean values
      expect(typeof agent.tools).toBe("object")
      for (const [tool, enabled] of Object.entries(agent.tools)) {
        expect(typeof enabled).toBe("boolean")
      }
    },
  })
})

test("{{agentName}} agent appears in agent list", async () => {
  await using tmp = await tmpdir({
    init: async (dir) => {
      const agentContent = await Bun.file(".opencode/agent/{{agentName}}.md").text()
      await Bun.write(
        path.join(dir, ".opencode/agent/{{agentName}}.md"),
        agentContent
      )
    },
  })

  await Instance.provide({
    directory: tmp.path,
    fn: async () => {
      const agents = await Agent.list()
      const agent = agents.find((a) => a.name === "{{agentName}}")

      expect(agent).toBeDefined()
    },
  })
})
```

Run the tests to verify they pass.
